  for(const[name,b]of Object.entries(after)){const a=before[name];if((a.x-1.55)*(b.x-1.55)<=0&&Math.abs(b.x-a.x)>1e-9){const t=(1.55-a.x)/(b.x-a.x);if(a.y+(b.y-a.y)*t-clearanceRadius(name)<=.26+BAR_RADIUS)return true;}}
  return false;
