function finishStep(s,dt){
  const before=s.finishTime;s.finishTime+=dt;const p=clamp(s.finishTime/1.6),u=smooth(p);s.x=s.finishX+3.15*u;s.y=s.finishY+s.finishArc*Math.sin(Math.PI*p);
