const baselineBytes=actual(new URL('../../docs/courtesy-copy-preview/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'6d826f5052a3210a1d699fcff6c056c3f82c617b7f815b0a680ff34fde1915bb');
